		require.NoError(t, err)
		assert.Equal(t, CheckpointSyncRemote{Name: "origin", Source: SyncRemoteSourceConfig}, got)
	})

	t.Run("captured remote no longer configured falls through to origin", func(t *testing.T) {
	if snap == nil {
		names, _ := read(ctx) //nolint:errcheck // unidentifiable repo: same best-effort contract
		return names
	}
	snap.mu.Lock()
	defer snap.mu.Unlock()
	if snap.orderedSet {
		return snap.ordered
	}
	names, err := read(ctx)
	if err != nil {
